#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(
            merge_ranges(&[(8, 10), (1, 3), (2, 6), (15, 18), (18, 20)]),
            vec![(1, 6), (8, 10), (15, 20)]
        );
    }

    #[test]
    fn empty() {
        assert_eq!(merge_ranges(&[]), vec![]);
    }

    #[test]
    fn contained() {
        assert_eq!(merge_ranges(&[(1, 10), (2, 3), (4, 5)]), vec![(1, 10)]);
    }

    #[test]
    fn no_overlap() {
        assert_eq!(merge_ranges(&[(5, 6), (1, 2), (3, 4)]), vec![(1, 2), (3, 4), (5, 6)]);
    }

    #[test]
    fn single_points() {
        assert_eq!(merge_ranges(&[(3, 3), (3, 3), (1, 2)]), vec![(1, 2), (3, 3)]);
    }
}
